import { cxF, cxToString } from "./gauss";
import type { Cx } from "./gauss";
import { P2 } from "./poly2";
import {
  collisionGridSearch,
  detJacobianIsOne,
  evalMap,
  fiberOver,
  findPolynomialInverse,
  gaussianGrid,
  injectivityCertificate,
  jacobianDet,
  pointString,
  valueString,
} from "./analyze";
import type {
  Collision,
  FiberReport,
  InjectivityCase,
} from "./analyze";

export interface CandidateReportLike {
  label: string;
  source: string;
  F1: string;
  F2: string;
  degrees: [number, number];
  terms: [number, number];
  det: string;
  detIsOne: boolean;
  offending: string[];
  inverseFound: boolean;
  inverseDegree: number;
  inverseG1: string | null;
  inverseG2: string | null;
  inverseVerified: boolean;
  composeCheck1: string;
  composeCheck2: string;
  composeCheck3: string;
  composeCheck4: string;
  collisions: string[];
  collisionPairs: Array<{
    P1: string;
    P2: string;
    value: string;
  }>;
  fibers: FiberReport[];
  injectivity: InjectivityCase[];
  certifiedInjective: boolean;
  isCounterexample: boolean;
  notes: string[];
}

export interface CandidateConfig {
  inverseDegreeBound: number;
  gridRadius: number;
  gridDenominators: number[];
  deepGridRadius: number;
  groebnerBudget: number;
}

interface VerifiedCollision {
  P1: [Cx, Cx];
  P2: [Cx, Cx];
  value: [Cx, Cx];
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  return String(error);
}

function validateConfig(cfg: CandidateConfig): void {
  if (!Number.isSafeInteger(cfg.inverseDegreeBound) || cfg.inverseDegreeBound < 0) {
    throw new RangeError("inverseDegreeBound must be a nonnegative safe integer");
  }

  if (!Number.isSafeInteger(cfg.gridRadius) || cfg.gridRadius < 0) {
    throw new RangeError("gridRadius must be a nonnegative safe integer");
  }

  if (!Number.isSafeInteger(cfg.deepGridRadius) || cfg.deepGridRadius < 0) {
    throw new RangeError("deepGridRadius must be a nonnegative safe integer");
  }

  if (!Number.isSafeInteger(cfg.groebnerBudget) || cfg.groebnerBudget < 0) {
    throw new RangeError("groebnerBudget must be a nonnegative safe integer");
  }

  if (!Array.isArray(cfg.gridDenominators)) {
    throw new TypeError("gridDenominators must be an array");
  }
}

function normalizedDenominators(values: number[]): number[] {
  const denominators = Array.from(
    new Set(
      values.filter(
        (value) => Number.isSafeInteger(value) && value > 0,
      ),
    ),
  ).sort((a, b) => a - b);

  return denominators.length === 0 ? [1] : denominators;
}

function rationalEqual(
  a: { n: bigint; d: bigint },
  b: { n: bigint; d: bigint },
): boolean {
  return (
    a.d !== 0n &&
    b.d !== 0n &&
    a.n * b.d === b.n * a.d
  );
}

function complexEqual(a: Cx, b: Cx): boolean {
  return (
    rationalEqual(a.re, b.re) &&
    rationalEqual(a.im, b.im)
  );
}

function pointEqual(a: [Cx, Cx], b: [Cx, Cx]): boolean {
  return complexEqual(a[0], b[0]) && complexEqual(a[1], b[1]);
}

function orderedPairKey(first: string, second: string): string {
  return first < second
    ? JSON.stringify([first, second])
    : JSON.stringify([second, first]);
}

function fiberTargets(): Array<[Cx, Cx]> {
  return [
    [cxF(0), cxF(0)],
    [cxF(1), cxF(1)],
    [
      cxF(2),
      {
        re: { n: 1n, d: 2n },
        im: { n: 0n, d: 1n },
      },
    ],
  ];
}

function verifyCollision(
  F1: P2,
  F2: P2,
  hit: Collision,
): VerifiedCollision | null {
  if (pointEqual(hit.P1, hit.P2)) {
    return null;
  }

  const firstValue = evalMap(F1, F2, hit.P1);
  const secondValue = evalMap(F1, F2, hit.P2);

  if (!pointEqual(firstValue, secondValue)) {
    return null;
  }

  return {
    P1: hit.P1,
    P2: hit.P2,
    value: firstValue,
  };
}

function collectCollisions(
  F1: P2,
  F2: P2,
  hits: Collision[],
  pairs: CandidateReportLike["collisionPairs"],
  lines: string[],
  seen: Set<string>,
  notes: string[],
): void {
  for (const hit of hits) {
    let verified: VerifiedCollision | null;

    try {
      verified = verifyCollision(F1, F2, hit);
    } catch (error) {
      notes.push(
        `collision candidate could not be verified: ${errorMessage(error)}`,
      );
      continue;
    }

    if (verified === null) {
      notes.push(
        "collision candidate rejected: distinct points with equal images were not verified",
      );
      continue;
    }

    const first = pointString(verified.P1);
    const second = pointString(verified.P2);
    const key = orderedPairKey(first, second);

    if (seen.has(key)) {
      continue;
    }

    seen.add(key);

    const value = valueString(verified.value);

    pairs.push({
      P1: first,
      P2: second,
      value,
    });

    lines.push(
      `F(${first}) = F(${second}) = ${value} [P1 != P2, images independently re-evaluated and equal]`,
    );
  }
}

export function analyzeCandidate(
  F1: P2,
  F2: P2,
  label: string,
  source: string,
  cfg: CandidateConfig,
  runInjectivity = true,
): CandidateReportLike {
  validateConfig(cfg);

  const notes: string[] = [];
  const detCheck = detJacobianIsOne(F1, F2);
  const determinant = jacobianDet(F1, F2);
  const det = determinant.toString();

  if (detCheck.isOne && det !== "1") {
    notes.push(
      `determinant representation differs from the exact unit check: ${det}`,
    );
  }

  if (!detCheck.isOne && det === "1") {
    notes.push(
      "determinant checks disagree: the string representation is 1, but the exact unit check failed",
    );
  }

  const inverse = findPolynomialInverse(
    F1,
    F2,
    cfg.inverseDegreeBound,
  );

  let composeCheck1 = "n/a";
  let composeCheck2 = "n/a";
  let composeCheck3 = "n/a";
  let composeCheck4 = "n/a";
  let inverseVerified = false;

  if (inverse.found && inverse.G1 !== null && inverse.G2 !== null) {
    try {
      const residual1 = inverse.G1
        .compose(F1, F2)
        .sub(P2.varX());
      const residual2 = inverse.G2
        .compose(F1, F2)
        .sub(P2.varY());
      const residual3 = F1
        .compose(inverse.G1, inverse.G2)
        .sub(P2.varX());
      const residual4 = F2
        .compose(inverse.G1, inverse.G2)
        .sub(P2.varY());

      composeCheck1 = residual1.isZero()
        ? "0"
        : residual1.toString();
      composeCheck2 = residual2.isZero()
        ? "0"
        : residual2.toString();
      composeCheck3 = residual3.isZero()
        ? "0"
        : residual3.toString();
      composeCheck4 = residual4.isZero()
        ? "0"
        : residual4.toString();

      inverseVerified =
        residual1.isZero() &&
        residual2.isZero() &&
        residual3.isZero() &&
        residual4.isZero();

      if (inverseVerified) {
        notes.push(
          `two-sided polynomial inverse verified in degree ${inverse.degree}`,
        );

        if (!inverse.leftVerified || !inverse.rightVerified) {
          notes.push(
            "inverse-search flags disagree with the four recomputed composition identities",
          );
        }
      } else {
        notes.push(
          "inverse-search candidate failed at least one exact composition identity",
        );
      }
    } catch (error) {
      notes.push(
        `inverse verification failed: ${errorMessage(error)}`,
      );
    }
  } else if (inverse.found) {
    notes.push(
      "inverse search reported success without both inverse components",
    );
  } else {
    notes.push(
      `no polynomial inverse of degree <= ${cfg.inverseDegreeBound} was found`,
    );
  }

  const denominators = normalizedDenominators(
    cfg.gridDenominators,
  );

  const collisionPairs: CandidateReportLike["collisionPairs"] = [];
  const collisionLines: string[] = [];
  const seenPairs = new Set<string>();

  if (!inverseVerified) {
    try {
      const initialGrid = gaussianGrid(
        cfg.gridRadius,
        denominators,
      );

      const initialHits = collisionGridSearch(
        F1,
        F2,
        initialGrid,
        4,
      );

      collectCollisions(
        F1,
        F2,
        initialHits,
        collisionPairs,
        collisionLines,
        seenPairs,
        notes,
      );
    } catch (error) {
      notes.push(
        `initial collision search failed: ${errorMessage(error)}`,
      );
    }

    if (collisionPairs.length === 0 && detCheck.isOne) {
      const deepDenominators = normalizedDenominators([
        ...denominators,
        1,
        2,
      ]);

      try {
        const deepGrid = gaussianGrid(
          cfg.deepGridRadius,
          deepDenominators,
        );

        const deepHits = collisionGridSearch(
          F1,
          F2,
          deepGrid,
          4,
        );

        collectCollisions(
          F1,
          F2,
          deepHits,
          collisionPairs,
          collisionLines,
          seenPairs,
          notes,
        );

        notes.push(
          `deep exact grid searched with radius ${cfg.deepGridRadius} and denominators {${deepDenominators.join(", ")}}`,
        );
      } catch (error) {
        notes.push(
          `deep collision search failed: ${errorMessage(error)}`,
        );
      }
    }
  } else {
    notes.push(
      "collision search skipped because a verified two-sided inverse proves injectivity",
    );
  }

  const fibers: FiberReport[] = [];

  try {
    const fiberGrid = gaussianGrid(
      cfg.gridRadius > 0 ? cfg.gridRadius : 3,
      denominators,
    );

    for (const target of fiberTargets()) {
      try {
        fibers.push(
          fiberOver(F1, F2, target, fiberGrid),
        );
      } catch (error) {
        notes.push(
          `fibre computation over (${cxToString(target[0])}, ${cxToString(target[1])}) failed: ${errorMessage(error)}`,
        );
      }
    }
  } catch (error) {
    notes.push(
      `fibre grid construction failed: ${errorMessage(error)}`,
    );
  }

  const isSmallMap =
    F1.degree() <= 2 &&
    F2.degree() <= 2;

  const needsCertificate =
    runInjectivity &&
    detCheck.isOne &&
    collisionPairs.length === 0 &&
    (!inverseVerified || isSmallMap);

  let injectivity: InjectivityCase[] = [];
  let certifiedInjective = inverseVerified;

  if (needsCertificate) {
    try {
      const certificate = injectivityCertificate(
        F1,
        F2,
        cfg.groebnerBudget,
      );

      injectivity = certificate.cases;

      if (certificate.certifiedInjective) {
        certifiedInjective = true;
        notes.push(
          "Groebner injectivity certificate verified",
        );
      } else if (isSmallMap && inverseVerified) {
        notes.push(
          "Groebner certificate did not independently verify a map with a verified inverse",
        );
      }
    } catch (error) {
      notes.push(
        `injectivity certificate failed: ${errorMessage(error)}`,
      );
    }
  }

  const inconsistent =
    collisionPairs.length > 0 &&
    certifiedInjective;

  if (inconsistent) {
    notes.push(
      "INTERNAL INCONSISTENCY: a verified collision coexists with an injectivity certificate; no counterexample conclusion is drawn",
    );
  }

  const isCounterexample =
    detCheck.isOne &&
    collisionPairs.length > 0 &&
    !inconsistent;

  if (isCounterexample) {
    notes.push(
      "distinct points with the same exactly re-evaluated image were found for a map whose Jacobian determinant passed the exact unit check",
    );
  }

  return {
    label,
    source,
    F1: F1.toString(),
    F2: F2.toString(),
    degrees: [F1.degree(), F2.degree()],
    terms: [F1.size(), F2.size()],
    det,
    detIsOne: detCheck.isOne,
    offending: detCheck.offending.map(
      (item) => `${cxToString(item.coeff)}*${item.mono}`,
    ),
    inverseFound: inverse.found,
    inverseDegree: inverse.degree,
    inverseG1:
      inverse.G1 === null
        ? null
        : inverse.G1.toString(),
    inverseG2:
      inverse.G2 === null
        ? null
        : inverse.G2.toString(),
    inverseVerified,
    composeCheck1,
    composeCheck2,
    composeCheck3,
    composeCheck4,
    collisions: collisionLines,
    collisionPairs,
    fibers,
    injectivity,
    certifiedInjective,
    isCounterexample,
    notes,
  };
}

