  gridRadius: number;
  gridDenominators: number[];
  deepGridRadius: number;
  groebnerBudget: number;
}

type Point = [Cx, Cx];

interface CollisionRecord {
  P1: Point;
  P2: Point;
  value: Point;
}

interface ImageEntry {
  point: Point;
  image: Point;
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  if (typeof error === "string") {
    return error;
  }
  return String(error);
