function validateConfig(cfg: CandidateConfig): void {
  if (!Number.isSafeInteger(cfg.inverseDegreeBound) || cfg.inverseDegreeBound < 0) {
    throw new RangeError("inverseDegreeBound must be a nonnegative safe integer");
  }
  if (!Number.isSafeInteger(cfg.gridRadius) || cfg.gridRadius < 0) {
    throw new RangeError("gridRadius must be a nonnegative safe integer");
  }
  if (!Number.isSafeInteger(cfg.deepGridRadius) || cfg.deepGridRadius < 0) {
    throw new RangeError("deepGridRadius must be a nonnegative safe integer");
  }
  if (!Number.isSafeInteger(cfg.groebnerBudget) || cfg.groebnerBudget < 0) {
    throw new RangeError("groebnerBudget must be a nonnegative safe integer");
  }
  if (!Array.isArray(cfg.gridDenominators)) {
    throw new TypeError("gridDenominators must be an array");
  }
