function normalizedDenominators(values: number[]): number[] {
  const result = Array.from(
    new Set(values.filter((value) => Number.isSafeInteger(value) && value > 0)),
  ).sort((a, b) => a - b);
  return result.length > 0 ? result : [1];
}

function rationalKey(value: { n: bigint; d: bigint }): string {
  if (value.d === 0n) {
    throw new RangeError("A rational number has a zero denominator");
  }
  if (value.n === 0n) {
    return "0";
  }
  let numerator = value.n;
  let denominator = value.d;
  if (denominator < 0n) {
    numerator = -numerator;
    denominator = -denominator;
  }
  let a = numerator < 0n ? -numerator : numerator;
  let b = denominator;
  while (b !== 0n) {
    const remainder = a % b;
    a = b;
    b = remainder;
  }
  return `${numerator / a}/${denominator / a}`;
}

function complexKey(value: Cx): string {
  return JSON.stringify([rationalKey(value.re), rationalKey(value.im)]);
}

function pointKey(point: Point): string {
  return JSON.stringify([complexKey(point[0]), complexKey(point[1])]);
}

function rationalEqual(
  first: { n: bigint; d: bigint },
  second: { n: bigint; d: bigint },
): boolean {
  if (first.d === 0n || second.d === 0n) {
    throw new RangeError("A rational number has a zero denominator");
  }
  return first.n * second.d === second.n * first.d;
}

function complexEqual(first: Cx, second: Cx): boolean {
  return (
    rationalEqual(first.re, second.re) &&
    rationalEqual(first.im, second.im)
  );
}

function pointEqual(first: Point, second: Point): boolean {
  return (
    complexEqual(first[0], second[0]) &&
    complexEqual(first[1], second[1])
  );
}

class CollisionSearch {
  private readonly F1: P2;
  private readonly F2: P2;
  private readonly limit: number;
  private readonly seenPoints = new Set<string>();
  private readonly images = new Map<string, ImageEntry>();
  readonly collisions: CollisionRecord[] = [];

  constructor(F1: P2, F2: P2, limit: number) {
    this.F1 = F1;
    this.F2 = F2;
    this.limit = limit;
  }

  get evaluatedPoints(): number {
    return this.seenPoints.size;
  }

  run(grid: Cx[]): number {
    let evaluated = 0;
    for (const x of grid) {
      for (const y of grid) {
        const point: Point = [x, y];
        const key = pointKey(point);
        if (this.seenPoints.has(key)) {
          continue;
        }
        const image = evalMap(this.F1, this.F2, point);
        const imageKey = pointKey(image);
        this.seenPoints.add(key);
        evaluated += 1;
        const previous = this.images.get(imageKey);
        if (previous === undefined) {
          this.images.set(imageKey, { point, image });
          continue;
        }
        if (this.collisions.length < this.limit) {
          this.verify(previous, point, image);
        }
      }
    }
    return evaluated;
  }

  private verify(previous: ImageEntry, point: Point, recordedImage: Point): void {
    if (pointEqual(previous.point, point)) {
      throw new Error("Distinct grid keys produced the same exact point");
    }
    const firstImage = evalMap(this.F1, this.F2, previous.point);
    const secondImage = evalMap(this.F1, this.F2, point);
    if (
      !pointEqual(previous.image, firstImage) ||
      !pointEqual(recordedImage, secondImage) ||
      !pointEqual(firstImage, secondImage)
    ) {
      throw new Error("An image-key match failed independent exact re-evaluation");
    }
    this.collisions.push({
      P1: previous.point,
      P2: point,
      value: firstImage,
    });
  }
}

function fiberTargets(): Point[] {
  return [
    [cxF(0), cxF(0)],
    [cxF(1), cxF(1)],
    [
      cxF(2),
      {
        re: { n: 1n, d: 2n },
        im: { n: 0n, d: 1n },
      },
    ],
  ];
}

export function analyzeCandidate(
  F1: P2,
  F2: P2,
  label: string,
  source: string,
  cfg: CandidateConfig,
  runInjectivity = true,
): CandidateReportLike {
  validateConfig(cfg);
  const notes: string[] = [];
  const detCheck = detJacobianIsOne(F1, F2);
  const det = jacobianDet(F1, F2);
  if (detCheck.isOne && det.toString() !== "1") {
    notes.push(
      `determinant normalization notice: the exact unit check succeeded, but the string representation is ${det.toString()}`,
    );
  }
  if (!detCheck.isOne && det.toString() === "1") {
    notes.push(
      "determinant inconsistency: the string representation is 1, but the exact unit check failed",
    );
