    const residual4 = F2.compose(inverse.G1, inverse.G2).sub(P2.varY());
    composeCheck1 = residual1.isZero() ? "0" : residual1.toString();
    composeCheck2 = residual2.isZero() ? "0" : residual2.toString();
    composeCheck3 = residual3.isZero() ? "0" : residual3.toString();
    composeCheck4 = residual4.isZero() ? "0" : residual4.toString();
