        );
      }
    } else {
      notes.push(
        "the proposed polynomial inverse failed at least one exact composition identity",
      );
    }
  } else if (inverse.found) {
    notes.push(
      "inverse search reported success without returning both inverse polynomials",
    );
  } else {
    notes.push(
      `no polynomial inverse of degree <= ${cfg.inverseDegreeBound} was found`,
    );
